// streamreaderSatInertList answers zeros where List should act.
type streamreaderSatInertList struct{ streamreader.StreamReader }

// A stream's zero value is a nil iterator, and ranging over one panics before
// the law is asked — so answering nothing means an empty sequence, not none.
func (m streamreaderSatInertList) List(p0 context.Context) iter.Seq2[streamreader.Value, error] {
	return testkit.EmptySeq2(m.StreamReader.List(p0))
}

// streamreaderSatFlickerList answers zeros every second
// call, where List should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type streamreaderSatFlickerList struct {
	streamreader.StreamReader
	flip atomic.Int64
}

func (m *streamreaderSatFlickerList) List(p0 context.Context) (z0 iter.Seq2[streamreader.Value, error]) {
	if m.flip.Add(1)%2 == 0 {
		// Empty rather than nil: a nil iterator panics when drained.
		return testkit.EmptySeq2(m.StreamReader.List(p0))
	}
	return m.StreamReader.List(p0)
}

